import { authorize_guest_join } from "../../../authorize/authorize_guest_join";
import { authorize_guest_refresh } from "../../../authorize/authorize_guest_refresh";

export async function test_api_guest_join_repeat_returns_new_tokens(
  connection: api.IConnection,
): Promise<void> {
  const firstJoinConnection: api.IConnection = { host: connection.host };
  const firstJoinInput = {
    display_name: RandomGenerator.name(),
    password: typia.assert<IMultiUserTodoUserProfile.IJoin["password"]>(
      typia.random<string & tags.Format<"password">>(),
    ),
    href: "https://example.com/guest/join",
    referrer: "https://example.com/",
  } satisfies IMultiUserTodoUserProfile.IJoin;
  const first = await authorize_guest_join(firstJoinConnection, {
    body: firstJoinInput,
  });
  typia.assert(first);
  const firstAccess = first.token.access;
  const firstRefresh = first.token.refresh;
  const firstProfileId = first.id;
  const firstDisplayName = first.display_name;
  TestValidator.predicate(
    "first token.access must be non-empty",
    firstAccess.length > 0,
  );
  TestValidator.predicate(
    "first token.refresh must be non-empty",
    firstRefresh.length > 0,
  );
  TestValidator.equals("first deleted_at is null", first.deleted_at, null);
  TestValidator.predicate(
    "response must not include password",
    !("password" in first as unknown as Record<string, unknown>),
  );
  TestValidator.predicate(
    "response must not echo password input",
    !JSON.stringify(first).includes(firstJoinInput.password),
  );

  const secondJoinConnection: api.IConnection = { host: connection.host };
  const secondJoinInput = {
    display_name: RandomGenerator.name(),
    password: typia.assert<IMultiUserTodoUserProfile.IJoin["password"]>(
      typia.random<string & tags.Format<"password">>(),
    ),
    href: "https://example.com/guest/join",
    referrer: "https://example.com/",
  } satisfies IMultiUserTodoUserProfile.IJoin;
  const second = await authorize_guest_join(secondJoinConnection, {
    body: secondJoinInput,
  });
  typia.assert(second);
  const secondAccess = second.token.access;
  const secondRefresh = second.token.refresh;
  const secondProfileId = second.id;
  const secondDisplayName = second.display_name;
  TestValidator.predicate(
    "second token.access must be non-empty",
    secondAccess.length > 0,
  );
  TestValidator.predicate(
    "second token.refresh must be non-empty",
    secondRefresh.length > 0,
  );
  TestValidator.equals("second deleted_at is null", second.deleted_at, null);
  TestValidator.predicate(
    "profile id should be a non-empty uuid",
    secondProfileId.length > 0,
  );
  TestValidator.predicate(
    "display name should be non-empty",
    secondDisplayName.length > 0,
  );
  TestValidator.predicate(
    "first display name should be non-empty",
    firstDisplayName.length > 0,
  );
  TestValidator.predicate(
    "at least one token value should differ",
    firstAccess !== secondAccess || firstRefresh !== secondRefresh,
  );
  TestValidator.predicate(
    "second response must not include password",
    !("password" in second as unknown as Record<string, unknown>),
  );
  TestValidator.predicate(
    "second response must not echo second password input",
    !JSON.stringify(second).includes(secondJoinInput.password),
  );
}

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import type { IMultiUserTodoUserProfile } from "@ORGANIZATION/PROJECT-api/lib/structures/IMultiUserTodoUserProfile";
import { DeepPartial } from "@ORGANIZATION/PROJECT-api/lib/typings/DeepPartial";
import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import { randint } from "tstl";
import typia, { tags } from "typia";

import { authorize_guest_join } from "../../../authorize/authorize_guest_join";
import { authorize_guest_refresh } from "../../../authorize/authorize_guest_refresh";

export async function test_api_guest_refresh_success_issues_new_tokens(
  connection: api.IConnection,
): Promise<void> {
  // 1. Guest join obtains a valid guest authorization response.
  const guestConnectionForJoin: api.IConnection = { host: connection.host };
  const joinInput = {
    display_name: RandomGenerator.name(),
    password: typia.random<
      string & tags.MinLength<1> & tags.Format<"password">
    >(),
    href: "https://example.com/guest/join",
    referrer: "https://example.com/guest/join?ref=1",
    ip: "127.0.0.1",
  } satisfies IMultiUserTodoUserProfile.IJoin;
  const joined = await authorize_guest_join(guestConnectionForJoin, {
    body: joinInput,
  });
  typia.assert(joined);
  // 2. Guest refresh issues a new token pair using the join refresh credential.
  const guestConnectionForRefresh: api.IConnection = { host: connection.host };
  const refreshed = await authorize_guest_refresh(guestConnectionForRefresh, {
    body: {
      refreshToken: joined.token.refresh,
    } satisfies IMultiUserTodoUserProfile.IRefresh,
  });
  typia.assert(refreshed);
  // Token pair basics (business logic assertions).
  TestValidator.predicate(
    "refreshed access token should be non-empty",
    refreshed.token.access.length > 0,
  );
  TestValidator.predicate(
    "refreshed refresh token should be non-empty",
    refreshed.token.refresh.length > 0,
  );
  TestValidator.predicate(
    "refreshed access expiration should be present and non-empty",
    refreshed.token.expired_at.length > 0,
  );
  TestValidator.predicate(
    "refreshed refreshable-until should be present and non-empty",
    refreshed.token.refreshable_until.length > 0,
  );
  // Same guest principal identity as join response.
  TestValidator.equals(
    "principal profile id should be consistent",
    refreshed.id,
    joined.id,
  );
  TestValidator.equals(
    "principal user id should be consistent",
    refreshed.multi_user_todo_user_id,
    joined.multi_user_todo_user_id,
  );
  // New tokens should be issued (token rotation).
  TestValidator.notEquals(
    "access token should differ after refresh",
    joined.token.access,
    refreshed.token.access,
  );
  TestValidator.notEquals(
    "refresh token should differ after refresh",
    joined.token.refresh,
    refreshed.token.refresh,
  );
}

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import type { IMultiUserTodoUserProfile } from "@ORGANIZATION/PROJECT-api/lib/structures/IMultiUserTodoUserProfile";
import { DeepPartial } from "@ORGANIZATION/PROJECT-api/lib/typings/DeepPartial";
import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import { randint } from "tstl";
import typia, { tags } from "typia";

import { authorize_guest_join } from "../../../authorize/authorize_guest_join";
import { authorize_guest_refresh } from "../../../authorize/authorize_guest_refresh";

export async function test_api_guest_refresh_multiple_renewals_keep_principal_identity(
  connection: api.IConnection,
): Promise<void> {
  const guestConnection: api.IConnection = { host: connection.host };
  const initialGuestInput = {
    display_name: RandomGenerator.name(),
    password: "Passw0rd!1234",
    href: "https://example.com/guest/join",
    referrer: "https://example.com/guest",
    ip: "127.0.0.1",
  } satisfies IMultiUserTodoUserProfile.IJoin;
  const joined = await authorize_guest_join(guestConnection, {
    body: initialGuestInput,
  });
  typia.assert(joined);
  const refreshTokenA: string = joined.token.refresh;
  const joinedPrincipalId: string = joined.id;
  const joinedPrincipalUserId: string = joined.multi_user_todo_user_id;
  const firstRefreshConnection: api.IConnection = { host: connection.host };
  const firstRefresh = await authorize_guest_refresh(firstRefreshConnection, {
    body: {
      refreshToken: refreshTokenA,
    } satisfies IMultiUserTodoUserProfile.IRefresh,
  });
  typia.assert(firstRefresh);
  const refreshTokenB: string = firstRefresh.token.refresh;
  TestValidator.equals(
    "principal id should remain identical after first refresh",
    firstRefresh.id,
    joinedPrincipalId,
  );
  TestValidator.equals(
    "principal multi_user_todo_user_id should remain identical after first refresh",
    firstRefresh.multi_user_todo_user_id,
    joinedPrincipalUserId,
  );
  TestValidator.notEquals(
    "access token should change after first refresh",
    firstRefresh.token.access,
    joined.token.access,
  );
  TestValidator.notEquals(
    "refresh token should change after first refresh",
    firstRefresh.token.refresh,
    refreshTokenA,
  );
  const joinedExpiredAtMs = Date.parse(joined.token.expired_at);
  const firstExpiredAtMs = Date.parse(firstRefresh.token.expired_at);
  TestValidator.predicate(
    "access token expiration should be refreshed after first refresh",
    () =>
      Number.isFinite(joinedExpiredAtMs) && Number.isFinite(firstExpiredAtMs)
        ? firstExpiredAtMs > joinedExpiredAtMs
        : false,
  );
  const joinedRefreshableUntilMs = Date.parse(joined.token.refreshable_until);
  const firstRefreshableUntilMs = Date.parse(
    firstRefresh.token.refreshable_until,
  );
  TestValidator.predicate(
    "refreshable deadline should be refreshed/extended after first refresh",
    () =>
      Number.isFinite(joinedRefreshableUntilMs) &&
      Number.isFinite(firstRefreshableUntilMs)
        ? firstRefreshableUntilMs >= joinedRefreshableUntilMs
        : false,
  );
  const secondRefreshConnection: api.IConnection = { host: connection.host };
  const secondRefresh = await authorize_guest_refresh(secondRefreshConnection, {
    body: {
      refreshToken: refreshTokenB,
    } satisfies IMultiUserTodoUserProfile.IRefresh,
  });
  typia.assert(secondRefresh);
  TestValidator.equals(
    "principal id should remain identical after second refresh",
    secondRefresh.id,
    joinedPrincipalId,
  );
  TestValidator.equals(
    "principal multi_user_todo_user_id should remain identical after second refresh",
    secondRefresh.multi_user_todo_user_id,
    joinedPrincipalUserId,
  );
  TestValidator.notEquals(
    "access token should change after second refresh",
    secondRefresh.token.access,
    firstRefresh.token.access,
  );
  TestValidator.notEquals(
    "refresh token should change after second refresh",
    secondRefresh.token.refresh,
    refreshTokenB,
  );
  const firstExpiredAtMs2 = Date.parse(secondRefresh.token.expired_at);
  TestValidator.predicate(
    "access token expiration should be refreshed after second refresh",
    () =>
      Number.isFinite(firstExpiredAtMs2)
        ? firstExpiredAtMs2 > firstExpiredAtMs
        : false,
  );
  const firstRefreshableUntilMs2 = Date.parse(
    secondRefresh.token.refreshable_until,
  );
  TestValidator.predicate(
    "refreshable deadline should be refreshed/extended after second refresh",
    () =>
      Number.isFinite(firstRefreshableUntilMs2)
        ? firstRefreshableUntilMs2 >= firstRefreshableUntilMs
        : false,
  );
}

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import type { IMultiUserTodoUserProfile } from "@ORGANIZATION/PROJECT-api/lib/structures/IMultiUserTodoUserProfile";
import { DeepPartial } from "@ORGANIZATION/PROJECT-api/lib/typings/DeepPartial";
import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import { randint } from "tstl";
import typia, { tags } from "typia";

import { authorize_guest_join } from "../../../authorize/authorize_guest_join";
import { authorize_guest_refresh } from "../../../authorize/authorize_guest_refresh";

export async function test_api_guest_refresh_reused_refresh_token_does_not_issue_tokens(
  connection: api.IConnection,
): Promise<void> {
  const href = "https://example.com/guest/refresh-reuse";
  const referrer = "https://example.com/guest/refresh";
  // 1) Guest join
  const guestJoinConnection: api.IConnection = { host: connection.host };
  const joinInput = {
    ...typia.random<IMultiUserTodoUserProfile.IJoin>(),
    display_name: RandomGenerator.name(),
    href,
    referrer,
  } satisfies IMultiUserTodoUserProfile.IJoin;
  const authorizedA = await authorize_guest_join(guestJoinConnection, {
    body: joinInput,
  });
  typia.assert(authorizedA);
  const refreshTokenA: string = authorizedA.token.refresh;
  // 2) First refresh (rotate)
  const guestRefreshConnection: api.IConnection = { host: connection.host };
  const refreshInputA = {
    refreshToken: refreshTokenA,
  } satisfies IMultiUserTodoUserProfile.IRefresh;
  const authorizedB = await authorize_guest_refresh(guestRefreshConnection, {
    body: refreshInputA,
  });
  typia.assert(authorizedB);
  const refreshTokenB: string = authorizedB.token.refresh;
  TestValidator.notEquals(
    "refresh token rotated",
    refreshTokenA,
    refreshTokenB,
  );
  // 3) Reuse the previously used refresh token (must fail)
  const guestRefreshReuseConnection: api.IConnection = {
    host: connection.host,
  };
  const refreshInputReuse = {
    refreshToken: refreshTokenA,
  } satisfies IMultiUserTodoUserProfile.IRefresh;
  await TestValidator.httpError(
    "guest refresh must reject reused refresh token",
    [400, 401, 403],
    async () =>
      await authorize_guest_refresh(guestRefreshReuseConnection, {
        body: refreshInputReuse,
      }),
  );
  // Validate no destructive side effect: newest refresh token (B) should still work.
  const guestRefreshBConnection: api.IConnection = { host: connection.host };
  const refreshInputB = {
    refreshToken: refreshTokenB,
  } satisfies IMultiUserTodoUserProfile.IRefresh;
  const authorizedC = await authorize_guest_refresh(guestRefreshBConnection, {
    body: refreshInputB,
  });
  typia.assert(authorizedC);
}

