    await api.functional.multiUserTodo.member.todos.bulk_permanent_delete.bulkPermanentDelete(
      todoConnection,
      {
        body: {
          todoIds: [trashTodo.id],
        } satisfies IMultiUserTodo.IBulkPermanentDeleteRequest,
      },
    );
  });
}

